/*
 * --------------------------------------------------------------------------
 * 1. GLOBAL RESET & BASE STYLES
 * --------------------------------------------------------------------------
 * Ensures consistent rendering across browsers and establishes the base typography.
 */
*,
*::before,
*::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

/*
 * --------------------------------------------------------------------------
 * 2. CSS VARIABLES (Theming & Design Tokens)
 * --------------------------------------------------------------------------
 * Defines the core visual language. This allows for easy global changes.
 */
:root {
    /* Spacing */
    --spacing-unit: 1rem;
    --section-padding: 6rem;
    --container-max-width: 1200px;

    /* Colors (Default Minimalist Palette) */
    --color-primary: #1a237e; /* Deep Indigo/Blue - Primary Brand Color */
    --color-secondary: #e8eaf6; /* Light Lavender - Accent Background */
    --color-text: #212121; /* Dark Gray - Main Text */
    --color-background: #ffffff; /* Pure White - Page Background */
    --color-light-text: #757575; /* Medium Gray - Subtext */

    /* Typography */
    --font-family-base: 'Inter', 'Helvetica Neue', sans-serif;
    --font-weight-light: 300;
    --font-weight-regular: 400;
    --font-weight-bold: 700;
    --line-height-base: 1.6;
}

/* Base body styling */
body {
    font-family: var(--font-family-base);
    color: var(--color-text);
    background-color: var(--color-background);
    line-height: var(--line-height-base);
    scroll-behavior: smooth;
}

/* Utility class for consistent section padding */
.section-padding {
    padding: var(--section-padding) 0;
}

/* Container limits the content width on large screens */
.container {
    max-width: var(--container-max-width);
    margin: 0 auto;
    padding: 0 var(--spacing-unit);
}

/* --------------------------------------------------------------------------
 * 3. SECTION STYLES
 * --------------------------------------------------------------------------
 */

/* ==========================================================================
   HERO SECTION
   ========================================================================== */
#hero {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 80vh;
    text-align: center;
    background-color: var(--color-secondary);
    padding: 0;
}

.hero-content {
    max-width: 800px;
    padding: var(--section-padding);
}

.hero-content h1 {
    font-size: clamp(2.5rem, 5vw, 4rem);
    font-weight: var(--font-weight-bold);
    margin-bottom: var(--spacing-unit);
    line-height: 1.1;
}

.hero-content p {
    font-size: clamp(1rem, 2vw, 1.25rem);
    color: var(--color-light-text);
    margin-bottom: calc(var(--spacing-unit) * 2);
    font-weight: var(--font-weight-regular);
}

/* CTA Button Styling */
.cta-button {
    display: inline-block;
    padding: 0.75rem 2rem;
    background-color: var(--color-primary);
    color: var(--color-background);
    text-decoration: none;
    border: none;
    border-radius: 5px;
    font-weight: var(--font-weight-bold);
    cursor: pointer;
    transition: background-color 0.3s ease;
    letter-spacing: 1px;
    box-shadow: 0 4px 10px rgba(0, 0, 0, 0.1);
}

.cta-button:hover {
    background-color: #151a6d; /* Slightly darker primary */
    transform: translateY(-2px);
    box-shadow: 0 6px 15px rgba(0, 0, 0, 0.15);
}

/* ==========================================================================
   ABOUT SECTION
   ========================================================================== */
#about {
    background-color: var(--color-background);
}

.about-grid {
    display: flex;
    gap: 3rem;
    align-items: center;
    margin-top: 3rem;
}

.about-image-container {
    flex: 1;
    min-width: 250px;
    /* Placeholder styling for the image */
    background-color: var(--color-secondary);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 300px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
}

.about-text-content {
    flex: 2;
}

.about-text-content h2 {
    font-size: 2rem;
    color: var(--color-primary);
    margin-bottom: 1rem;
}

.about-text-content p {
    margin-bottom: 1.5rem;
    color: var(--color-text);
}

/* ==========================================================================
   PROJECTS GRID
   ========================================================================== */
#projects-grid {
    background-color: var(--color-secondary);
    text-align: center;
}

.projects-grid-container {
    display: grid;
    grid-template-columns: repeat(3, 1fr); /* Default: 3 columns */
    gap: 2rem;
    margin-top: 3rem;
}

/* Individual Project Card Styling */
.project-card {
    background-color: var(--color-background);
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    padding: 1.5rem;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    text-align: left;
}

.project-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 15px 30px rgba(0, 0, 0, 0.1);
}

.project-card h3 {
    font-size: 1.5rem;
    color: var(--color-primary);
    margin-bottom: 0.75rem;
}

.project-card p {
    font-size: 0.9rem;
    color: var(--color-light-text);
    flex-grow: 1;
}

.project-card .tech-stack {
    margin-top: 1rem;
    font-size: 0.8rem;
    color: #555;
    display: flex;
    gap: 0.5rem;
}

/* ==========================================================================
   CONTACT SECTION
   ========================================================================== */
#contact {
    background-color: var(--color-background);
}

.contact-form {
    max-width: 600px;
    margin: 0 auto;
    padding: 2rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.contact-form label {
    display: block;
    margin-bottom: 0.25rem;
    font-weight: var(--font-weight-bold);
    color: var(--color-text);
}

.contact-form input[type="text"],
.contact-form input[type="email"],
.contact-form textarea {
    width: 100%;
    padding: 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.3s;
}

.contact-form input:focus,
.contact-form textarea:focus {
    border-color: var(--color-primary);
    outline: none;
    box-shadow: 0 0 0 3px rgba(26, 35, 126, 0.1);
}

.contact-form textarea {
    resize: vertical;
    min-height: 150px;
}

/* ==========================================================================
   RESPONSIVENESS (MEDIA QUERIES)
   ========================================================================== */

/* Tablet and smaller (Max 1024px) */
@media (max-width: 1024px) {
    .about-grid {
        flex-direction: column;
        text-align: center;
    }
    .about-image-container {
        margin-bottom: 2rem;
    }
}

/* Mobile (Max 768px) */
@media (max-width: 768px) {
    /* General Section Adjustments */
    .section-padding {
        padding: 4rem 0;
    }

    /* Hero Adjustments */
    .hero-content h1 {
        font-size: 2.5rem;
    }

    /* Projects Grid: Switch to 2 columns */
    .projects-grid-container {
        grid-template-columns: repeat(2, 1fr);
    }
}

/* Small Mobile (Max 480px) */
@media (max-width: 480px) {
    /* Projects Grid: Switch to 1 column */
    .projects-grid-container {
        grid-template-columns: 1fr;
    }

    /* Contact Form Adjustments */
    .contact-form {
        padding: 1rem;
    }
}

