import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import "./index.css";
import App from "./App";

// index.html declares <div id="root"></div> before this module script runs.
// If that contract is broken we fail loudly rather than letting React throw
// an opaque error from inside its own internals.
const rootElement = document.getElementById("root");

if (!rootElement) {
  throw new Error(
    'Root element #root not found in index.html — expected <div id="root"></div> in the body.',
