/* ---------------------------------------------------------------------------
   Design tokens
   Direction: calm editorial. Warm paper background, ink text, one amber accent.
   Serif display face for headings, system sans for UI, mono for code.
   Every value below is consumed through var() — no raw hex in component rules.
   --------------------------------------------------------------------------- */
:root {
  /* Colour — neutral ramp + single accent */
  --paper: #faf7f2;
  --paper-raised: #ffffff;
  --paper-muted: #f1ece3;
  --ink: #1c1a17;
  --ink-soft: #4a453d;
  --ink-faint: #6f685c;
  --rule: #ddd5c8;
  --accent: #a4551a;
  --accent-strong: #7f3f11;
  --accent-tint: #f6e7d8;
  --focus: #1f5fa8;
  --on-accent: #ffffff;

  /* Spacing scale — 4/8/12/16/24/32/48/64 */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;
  --space-8: 64px;

  /* Type scale — 0.875 / 1 / 1.25 / 1.5 / 2.5rem */
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-md: 1.25rem;
  --text-lg: 1.5rem;
  --text-display: 2.5rem;

  --leading-tight: 1.15;
  --leading-snug: 1.35;
  --leading-body: 1.65;

  --font-sans: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --font-ui: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto,
    "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;

  --radius: 6px;
  --radius-lg: 12px;
  --radius-pill: 999px;
  --measure: 62ch;
  --shell: 1080px;

  --shadow-card: 0 1px 0 var(--rule), 0 8px 24px rgba(28, 26, 23, 0.06);
  --ease: 120ms ease-out;
}

/* ---------------------------------------------------------------------------
   Reset & base
   --------------------------------------------------------------------------- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background-color: var(--paper);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--text-base);
  line-height: var(--leading-body);
  -webkit-font-smoothing: antialiased;
}

h1,
h2,
h3 {
  margin: 0;
  font-family: var(--font-sans);
  font-weight: 600;
  letter-spacing: -0.01em;
}

p {
  margin: 0;
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

dl,
dd {
  margin: 0;
}

a {
  color: var(--accent-strong);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

a:hover {
  color: var(--accent);
}

code {
  font-family: var(--font-mono);
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: var(--radius);
}

/* ---------------------------------------------------------------------------
   Layout primitives
   --------------------------------------------------------------------------- */
.page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
}

.shell {
  width: 100%;
  max-width: var(--shell);
  margin-inline: auto;
  padding-inline: var(--space-5);
}

.section {
  padding-block: var(--space-8);
  border-top: 1px solid var(--rule);
}

.section--muted {
  background-color: var(--paper-muted);
}

.section__title {
  font-size: var(--text-lg);
  line-height: var(--leading-snug);
  max-width: 30ch;
  margin-top: var(--space-2);
  margin-bottom: var(--space-5);
}

.eyebrow {
  font-family: var(--font-ui);
  font-size: var(--text-sm);
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent-strong);
}

.lede {
  font-size: var(--text-md);
  line-height: var(--leading-snug);
  color: var(--ink-soft);
  max-width: var(--measure);
}

.prose {
  display: grid;
  gap: var(--space-4);
  max-width: var(--measure);
  color: var(--ink-soft);
}

.code {
  font-family: var(--font-mono);
  font-size: 0.9em;
  background-color: var(--paper-muted);
  border: 1px solid var(--rule);
  border-radius: var(--radius);
  padding: 0 var(--space-1);
}

/* ---------------------------------------------------------------------------
   Skip link
   --------------------------------------------------------------------------- */
.skip-link {
  position: absolute;
  left: var(--space-4);
  top: calc(-1 * var(--space-8));
  z-index: 10;
  background-color: var(--ink);
  color: var(--paper);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--radius);
  text-decoration: none;
  transition: top var(--ease);
}

.skip-link:focus {
  top: var(--space-4);
  color: var(--paper);
}

/* ---------------------------------------------------------------------------
   Header & nav
   --------------------------------------------------------------------------- */
.site-header {
  border-bottom: 1px solid var(--rule);
  background-color: var(--paper);
}

.site-header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-5);
  padding-block: var(--space-4);
