import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import "./index.css";

/**
 * Entry point for the portfolio site.
 *
 * `index.html` loads this module via
 * `<script type="module" src="/src/main.tsx">` and provides the
 * `<div id="root">` mount node. This file does exactly three things:
 *
 *   1. Pull in the shared global stylesheet (tokens, type scale, layout
 *      primitives) so every component's class hooks resolve.
 *   2. Import the composed `App` tree from `./App`.
 *   3. Mount it into `#root` with React 18's `createRoot`.
 *
 * No props, no events, no other exports.
 */

const container = document.getElementById("root");

if (!container) {
  throw new Error(
    'Portfolio: mount node "#root" was not found in index.html. ' +
      "The app cannot render without it."
  );
}

createRoot(container).render(
  <StrictMode>
    <App />
  </StrictMode>
);
