import { useEffect, useRef, useState } from "react";

/**
 * About — two-column bio + skills block.
 *
 * Owns the `#about` anchor that Vega's header nav links to.
 *
 * Layout is owned in-file (see the scoped <style> block below) so the
 * two-column requirement does not depend on a stylesheet authored elsewhere.
 * Class names are namespaced `about-*` to avoid colliding with any global
 * rules that may later be added to index.css.
 */

const SKILLS: string[] = [
  "TypeScript",
  "React",
  "HTML & CSS",
  "Accessibility",
  "Vite",
  "Node.js",
  "Git",
  "Figma",
];

export default function About() {
  const sectionRef = useRef<HTMLElement | null>(null);
  const [revealed, setRevealed] = useState(false);

  // Progressive enhancement: fade the block in once it scrolls into view.
  // If IntersectionObserver is unavailable, content is shown immediately.
  useEffect(() => {
    const node = sectionRef.current;
    if (!node) return;

    if (typeof IntersectionObserver === "undefined") {
      setRevealed(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            setRevealed(true);
            observer.disconnect();
            break;
          }
        }
      },
      { threshold: 0.15 }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

