        }

        @media (prefers-reduced-motion: reduce) {
          .about {
            opacity: 1;
            transform: none;
            transition: none;
          }
        }

        .about__title {
          margin: 0 0 0.5rem;
          font-size: 2rem;
          line-height: 1.15;
          letter-spacing: -0.02em;
          font-weight: 700;
        }

        .about__title::after {
          content: "";
          display: block;
          width: 3rem;
          height: 3px;
          margin-top: 0.75rem;
          border-radius: 999px;
          background: var(--about-accent);
        }

        .about__grid {
          display: grid;
          grid-template-columns: minmax(0, 1.35fr) minmax(0, 1fr);
          gap: 3rem;
          margin-top: 2.5rem;
          align-items: start;
        }

