/**
 * Footer — closing band of the portfolio page.
 *
 * Leaf component: no props, no state, no effects, no context.
 * Renders a copyright line and a list of social links.
 *
 * Styling lives in src/index.css (shared global sheet). The class hooks
 * emitted here are: .footer, .footer__inner, .footer__copy,
 * .footer__social, .footer__list, .footer__link.
 *
 * NOTE: the hrefs below are placeholders. Swap them for real profile URLs.
 */

type SocialLink = {
  label: string;
  href: string;
};

const SOCIAL_LINKS: SocialLink[] = [
  { label: "GitHub", href: "https://github.com/" },
  { label: "LinkedIn", href: "https://linkedin.com/" },
  { label: "Twitter", href: "https://twitter.com/" },
];

const OWNER_NAME = "Your Name";

const Footer = (): JSX.Element => {
  const year = new Date().getFullYear();

  return (
    <footer className="footer">
      <div className="container footer__inner">
        <p className="footer__copy">
