import { projects } from "../data/projects";

/**
 * Projects
 *
 * Presentational section. Renders the typed `projects` array from
 * `../data/projects` as a responsive card grid.
 *
 * Anchor target: `#projects` (reserved for Header/Hero navigation).
 * Layout class: `.container` (global, provided by index.css).
 * Section spacing: `.section` (global, provided by index.css).
 */
export default function Projects() {
  const hasProjects = Array.isArray(projects) && projects.length > 0;

  return (
    <section id="projects" className="container section" aria-labelledby="projects-heading">
      <header className="section-head">
        <p className="section-eyebrow">Selected work</p>
        <h2 id="projects-heading" className="section-title">
          Projects
        </h2>
        <p className="section-lede">
          A short list of things I have designed, built and shipped — from design systems
          to data-heavy interfaces.
        </p>
      </header>

      {hasProjects ? (
        <ul className="projects-grid">
          {projects.map((project, index) => {
            const key = project.id ?? `project-${index}`;
            const tags = project.tags ?? [];

            return (
              <li key={key} className="projects-grid__item">
                <article className="project-card">
                  <h3 className="project-card__title">{project.title}</h3>
                  <p className="project-card__description">{project.description}</p>

                  {tags.length > 0 ? (
                    <ul className="project-card__tags" aria-label="Technologies used">
                      {tags.map((tag) => (
                        <li key={tag} className="project-card__tag">
                          {tag}
                        </li>
                      ))}
                    </ul>
                  ) : null}

                  {project.href || project.repo ? (
                    <div className="project-card__links">
                      {project.href ? (
                        <a
                          className="project-card__link"
                          href={project.href}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          View project
                          <span className="project-card__link-arrow" aria-hidden="true">
                            →
                          </span>
                        </a>
                      ) : null}

                      {project.repo ? (
                        <a
                          className="project-card__link project-card__link--muted"
                          href={project.repo}
                          target="_blank"
                          rel="noopener noreferrer"
                        >
                          Source
                          <span className="project-card__link-arrow" aria-hidden="true">
                            →
                          </span>
                        </a>
                      ) : null}
                    </div>
                  ) : null}
                </article>
              </li>
            );
          })}
        </ul>
      ) : (
        <p className="projects-empty">No projects to show yet.</p>
      )}
    </section>
  );
}

