 * sections; #contact is owned by the Contact section.
 */
const NAV_LINKS: ReadonlyArray<NavLink> = [
  { href: "#about", label: "About" },
  { href: "#projects", label: "Projects" },
  { href: "#contact", label: "Contact" },
];

const HEADER_CSS = `
