/* Global stylesheet: design tokens, type scale, layout primitives. */

:root {
  --bg: #ffffff;
  --ink: #14161c;
  --muted: #4a4f5c;
  --accent: #6d5efc;
  --line: #e4e6ec;
  --surface: #f7f8fb;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-6: 24px;
  --space-8: 32px;
  --space-12: 48px;
  --space-16: 64px;
  --radius: 10px;
  --max-width: 1080px;
  --font-sans: system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial,
    sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

